// Self-checking testbench for block_embed_core — bit-exact against
// tools/tag_reference/embed.py and vectors generated by gen_block_embed_vectors.py.
//
// Run: vivado/scripts/run_sim.sh block_embed_core

`timescale 1ns / 1ps
`include "be_params.vh"

module block_embed_core_tb;

    localparam integer NV = BE_NUM_VECTORS;
    localparam integer DW = 16;

    reg clk = 0;
    reg rst_n = 0;

    reg signed [DW-1:0] sample_in = 0;
    reg                 valid_in = 0;
    reg [31:0]          var_in = 0;
    reg                 bit_in = 0;
    wire                ready_out;

    wire signed [DW-1:0] sample_out;
    wire [3:0]           sample_idx_out;
    wire [15:0]          delta_out;
    wire signed [31:0]   v_out;
    wire                 rbit_out;
    wire                 valid_out;

    reg [DW-1:0] in_mem    [0:NV*16-1];
    reg [DW-1:0] out_mem   [0:NV*16-1];
    reg [31:0]   var_mem   [0:NV-1];
    reg [3:0]    bit_mem   [0:NV-1];
    reg [3:0]    rbit_mem  [0:NV-1];
    reg [15:0]   delta_mem [0:NV-1];
    reg [31:0]   v_mem     [0:NV-1];

    block_embed_core #(
        .DATA_WIDTH(DW)
    ) dut (
        .clk(clk),
        .rst_n(rst_n),
        .sample_in(sample_in),
        .valid_in(valid_in),
        .var_in(var_in),
        .bit_in(bit_in),
        .ready_out(ready_out),
        .sample_out(sample_out),
        .sample_idx_out(sample_idx_out),
        .delta_out(delta_out),
        .v_out(v_out),
        .rbit_out(rbit_out),
        .valid_out(valid_out)
    );

    always #5 clk = ~clk;

    integer c, b, out_idx, timeout, errors;

    initial begin
        errors = 0;

        $readmemh("be_in.mem", in_mem);
        $readmemh("be_out.mem", out_mem);
        $readmemh("be_var.mem", var_mem);
        $readmemh("be_bit.mem", bit_mem);
        $readmemh("be_rbit.mem", rbit_mem);
        $readmemh("be_delta.mem", delta_mem);
        $readmemh("be_v.mem", v_mem);

        repeat (3) @(posedge clk);
        rst_n = 1;
        @(negedge clk);

        for (c = 0; c < NV; c = c + 1) begin
            // Feed 16 samples
            for (b = 0; b < 16; b = b + 1) begin
                @(negedge clk);
                while (!ready_out) @(negedge clk);
                sample_in = in_mem[c * 16 + b];
                var_in    = var_mem[c];
                bit_in    = bit_mem[c][0];
                valid_in  = 1;
                @(negedge clk);
                valid_in  = 0;
            end

            // Collect 16 output samples
            out_idx = 0;
            timeout = 0;
            while (out_idx < 16 && timeout < 200) begin
                @(negedge clk);
                if (valid_out) begin
                    if (sample_idx_out !== out_idx[3:0]) begin
                        errors = errors + 1;
                        $display("FAIL case %0d sample %0d: idx mismatch got %0d", c, out_idx, sample_idx_out);
                    end
                    if (sample_out !== out_mem[c * 16 + out_idx]) begin
                        errors = errors + 1;
                        $display("FAIL case %0d sample %0d: got %04x exp %04x", c, out_idx, sample_out, out_mem[c * 16 + out_idx]);
                    end
                    if (out_idx == 0) begin
                        if (delta_out !== delta_mem[c]) begin
                            errors = errors + 1;
                            $display("FAIL case %0d delta: got %04x exp %04x", c, delta_out, delta_mem[c]);
                        end
                        if (v_out !== v_mem[c]) begin
                            errors = errors + 1;
                            $display("FAIL case %0d v: got %08x exp %08x", c, v_out, v_mem[c]);
                        end
                        if (rbit_out !== rbit_mem[c][0]) begin
                            errors = errors + 1;
                            $display("FAIL case %0d rbit: got %0d exp %0d", c, rbit_out, rbit_mem[c][0]);
                        end
                    end
                    out_idx = out_idx + 1;
                end
                timeout = timeout + 1;
            end

            if (out_idx < 16) begin
                errors = errors + 1;
                $display("FAIL case %0d: timed out after %0d samples", c, out_idx);
            end
        end

        if (errors == 0) begin
            $display("PASS: all %0d vectors verified bit-exact!", NV);
            $finish(0);
        end else begin
            $display("FAIL: %0d errors across %0d vectors", errors, NV);
            $finish(1);
        end
    end

endmodule
